Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('43','Przyci¹ganie linki wyci¹gu dolnego w siadzie p³askim','Siadamy p³asko przed wyci¹giem dolnym nogi zaparte o stabilny punkt oparcia i chwytamy r¹czkê wyci¹gu. Przyci¹gamy j¹ do brzucha, utrzymuj¹c przez ca³y czas tu³ów w pozycji pionowej. W koñcowej fazie ruchu staramy siê œci¹gn¹æ ³opatki ku sobie. Po czym powoli, kontroluj¹c ruch opuszczamy ciê¿ar. Wdech przed rozpoczêciem przyci¹gania- wydech, gdy r¹czka jest przy brzuchu. R¹czka mo¿e byæ ró¿na(uchwyt w zwi¹zku z tym równie¿ mo¿e byæ ró¿ny','5');
