Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('45','Podci¹ganie (wios³owanie) w le¿eniu na ³aweczce poziomej','Jest to æwiczenie podobne do wios³owania w opadzie tu³owia, ale odci¹¿a ono dolny odcinek miêsni grzbietu-szczególnie polecane dla osób, które maj¹ k³opoty z t¹ w³aœnie czêœci¹. Technika podobna jak w æwiczeniu w opadzie. Tu³ów oparty o ³awkê poziom¹. £okcie przy æwiczeniu ze sztang¹','5');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('46','Martwy ci¹g','Stajemy przodem do sztangi, w rozkroku na szerokoœæ barków lub nieco szerszym, nogi lekko ugiête w kolanach, gryf sztangi nad palcami stóp, sztangê chwytamy nachwytem, nieco szerzej ni¿ barki. Klatka wypchniêta ku przodowi, tu³ów wyprostowany, g³owa lekko zadarta do góry. Æwiczenie polega na unoszeniu sztangi w górê poprzez prostowanie nóg i wyprost tu³owia. Ruch koñczymy przy pe³nym wyproœcie tu³owia-nie odchylamy go do ty³u-grozi to kontuzj¹.','5');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('47','Przysiady ze sztang¹ na barkach','Wchodzimy pod sztangê stoj¹c¹ na stojakach, barki opuszczone i odwiedzione w ty³, gryf sztangi dotyka naszego karku na miêœniach czworobocznych grzbietu(ich górnej czêœci), d³onie rozstawione w wygodnej i stabilnej pozycji na gryfie, klatka wypchniêta ku przodowi, naturalna krzywizna krêgos³upa-dolny odcinek grzbietu wypchniêty do przodu, rozstaw stóp w zale¿noœci od naszego poczucia stabilnoœci(zmiana rozstawu stóp powodowaæ bêdzie atak na miêœnie pod innym k¹tem), najlepiej nieco szerzej, ni¿ barki, ca³e stopy przylegaj¹ do pod³ogi, ciê¿ar ma opieraæ siê na piêtach, g³owa zadarta nieco do ty³u. Z tej pozycji nabieramy g³êboko powietrza i œci¹gamy sztangê ze stojaków i rozpoczynamy ruch w dó³','6');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('48','Syzyfki','-Æwiczenie to mo¿na wykonywaæ zarówno bez obci¹¿enia, jak i z nim. Chwytamy wtedy w jedn¹ rêkê kr¹¿ek i k³adziemy go sobie na klatce, drug¹ rêk¹ podpieramy siê dla zachowania równowagi czegoœ stabilnego. Æwiczenie polega na wykonaniu przysiadu z jednoczesnym mocnym odchyleniem tu³owia do ty³u i wspiêciem na palce stóp po³¹czonym z wypchniêciem kolan do przodu-dla lepszego rozci¹gniêcia miêœni górnej czêœci ud i zwiêkszenia poziomu trudnoœci æwiczenia.','6');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('49','Wypychanie ciê¿aru na suwnicy (maszynie)','Æwiczenie to mo¿na wykonywaæ na ró¿nego rodzaju suwnicach i maszynach, pod ró¿nymi k¹tami-zmiana u³o¿enia cia³a w æwiczeniu powoduje, ¿e atakujemy miêœnie pod ró¿nymi k¹tami-bardziej wszechstronnie. Bez wzglêdu na rodzaj maszyny i kat u³o¿enia cia³a, obowi¹zuj¹ wspólne zasady: siadamy na siedzisku, opieraj¹c stopy na platformie maszyny, ich rozstaw ok. szerokoœci ramion-ca³e stopy przylegaj¹ do platformy, nogi wyprostowane w kolanach,(ale nie zblokowane)-z tej pozycji nabieraj¹c powietrza rozpoczynamy powtórzenie','6');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('50','Przysiady wykroczne','Pozycja wyjœciowa taka, jak przy przysiadach zwyk³ych. Z tej pozycji stawiamy jedn¹ noga krok do przodu(na tyle du¿y, by po wykonaniu przysiadu do momentu ugiêcia nogi pod k¹tem 90 stopni-podudzia by³y prostopadle do pod³ogi, a uda równoleg³e), po czym wykonujemy na nodze wykrocznej przysiad, na tyle g³êboki, by noga ugiê³a siê pod k¹tem ok.90 stopni.','6');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('51','Wspiêcia na palce w staniu',' Æwiczenie to mo¿na wykonywaæ zarówno przy pomocy sztangi(gif 1), suwnicy Smitha(gif 1a) lub specjalnej maszyny(gif 1c). Mo¿na wykonywaæ je równie¿ bez obci¹¿enia, a tak¿e jednonó¿(gif 1b).Sztangê mo¿na równie¿ zast¹piæ sztangielk¹ trzyman¹ w d³oni(po tej samej stronie, co æwiczona noga: lewa noga- lewa rêka, prawa noga- prawa rêka). Istotnym elementem w tym æwiczeniu jest u¿ycie grubej podk³adki pod palce stóp, która pozwala zwiêkszyæ znacznie zakres ruchu, a co za tym idzie-poprawiæ efektywnoœæ æwiczenia. ','7');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('52','Wspiêcia na palce na "hack-maszynie"',' Zalecany jest rozs¹dny dobór ciê¿aru-taki, by nie „przeszkadza³” w poprawnym technicznie wykonaniu æwiczenia, ani nie sta³ siê powodem kontuzji-stawy skokowe s¹ bardzo delikatne i podatne na kontuzje-zatem b³êdy w technice wykonania æwiczenia skumulowane z du¿ym obci¹¿eniem, mog¹ byæ nader niebezpieczne.','7');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('53','Wypychanie ciê¿aru na maszynie/suwnicy palcami nóg','Jest to, jakby odwrotna wersja wspiêæ na Hack-maszynie- odwrotna jest pozycja-g³owa znajduje siê ni¿ej nóg. Pozycja wyjœciowa to siad na siedzisku maszyny/suwnicy, plecy oparte, nogi wyprostowane w kolanach, stopy dotykaj¹ do p³aszczyzny maszyny/suwnicy tylko palcami i stawami ³¹cz¹cymi je ze sródstopiem, miêœnie ³ydek rozci¹gniête maksymalnie. Z tej pozycji wypychamy ciê¿ar si³¹ miêsni ³ydek.','7');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('54','Odwrotne wspiêcia w staniu','Æwiczenie podobne do wspiêæ na palce- ró¿nica jest taka, ¿e podk³adki s¹ pod piêtami, a unosimy nie piêty, lecz œródstopia nóg. Pozycja taka, jak przy wspiêciach na palce, ale nie rozci¹gamy miêœni ³ydek w pocz¹tkowej fazie-tylko miêœnie piszczelowe.','7');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('55','Sk³ony w le¿eniu g³ow¹ w dó³','Wykonanie jak w æwiczeniu poprzednim-p³asko, ale pozycja wyjœciowa jest g³ow¹ w dó³ na ³awce skoœnej. Dla lepszego zaanga¿owania miêœni skoœnych brzucha w koñcowej fazie unoszenia tu³owia mo¿na wykonywaæ nim skrêty(gif 2a.). Jest to jednak wersja trudniejsza i bardziej nara¿aj¹ca na ewentualne kontuzje(mocniej obci¹¿a dolne partie grzbietu).','8');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('56','"Spinanie"/Unoszenie kolan w le¿eniu p³asko','Siadamy na ³awce, tu³ów wyprostowany,(najlepiej z podpor¹ pod plecy),za plecami mamy wyci¹g górny(zamiast r¹czki zaczepiona lina z wêz³ami na koñcach),chwytamy koniec liny(w ten sposób, ¿e otacza nam z ty³u kark), z tej pozycji wykonujemy sk³ony w przód na taka g³êbokoœæ, by nie odrywaæ dolnego odcinka pleców od oparcia, staraj¹c siê przez ca³y czas utrzymaæ dolny odcinek grzbietu wyprostowany. Powrotny ruch kontrolowany i w wolnym tempie. Bardzo podobne dzia³anie ma æwiczenie wykonane na specjalnej maszynie ','8');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('57','Sk³ony tu³owia z link¹ wyci¹gu siedz¹c','iadamy na ³awce, tu³ów wyprostowany,(najlepiej z podpor¹ pod plecy),za plecami mamy wyci¹g górny(zamiast r¹czki zaczepiona lina z wêz³ami na koñcach),chwytamy koniec liny(w ten sposób, ¿e otacza nam z ty³u kark), z tej pozycji wykonujemy sk³ony w przód na taka g³êbokoœæ, by nie odrywaæ dolnego odcinka pleców od oparcia, staraj¹c siê przez ca³y czas utrzymaæ dolny odcinek grzbietu wyprostowany. Powrotny ruch kontrolowany i w wolnym tempie. Bardzo podobne dzia³anie ma æwiczenie wykonane na specjalnej maszynie','8');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('58','Sk³ony boczne','tajemy w lekkim rozkroku(na szerokoœæ barków, lub nieco szerzej),tu³ów wyprostowany, w jedn¹ rêkê chwytamy sztangielkê, drug¹ zak³adamy sobie na g³owê(d³oni¹). Z tej pozycji wykonujemy sk³on w kierunku wolnej rêki, napinaj¹c miêœnie skoœne brzucha. Oddech bierzemy w momencie rozpoczêcia ruchu, wypuszczamy powietrze w momencie maksymalnego sk³onu. Powrót do pozycji wyjœciowej mo¿e byæ z przekroczeniem linii pionu(tu³owia)-zwiêksza to napiêcie miêœni skoœnych.','8');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('59','Uginanie ramion ze sztangielkami stoj¹c podchwytem (z "supinacj¹" nadgarstka)','Æwiczenie to mo¿na wykonywaæ zarówno w pozycji stoj¹cej, jak i siedz¹cej. Bardzo dobre, jako rozgrzewkowe przed ciê¿kimi seriami ze sztang¹, ale równie¿ jako samodzielne æwiczenie rozwijaj¹ce masê i kszta³t bicepsów. Polecane wykonanie z „supinacj¹” nadgarstka. Polega ona na stopniowym obracaniu d³oni w trakcie wykonywania æwiczenia.','9');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('60','Uginanie ramion ze sztang¹ na "modlitewniku"','Nogi rozstawiamy w taki sposób, by pozwoli³y nam utrzymaæ stabiln¹ pozycjê. Górna krawêdŸ modlitewnika powinna znaleŸæ siê pod naszymi pachami. Ramiona rozstawione na szerokoœæ barków-równolegle do siebie. Rozstaw d³oni, podobnie jak w æwiczeniu ze sztanga stoj¹c-w zale¿noœci od celu æwiczenia(zaanga¿owanie poszczególnych g³ów, jak w æwiczeniu ze sztang¹ stoj¹c).','9');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('61','Uginanie ramion ze sztangielkami w siadzie na ³awce skoœnej (z supinacj¹ nadgarstka)','est to jedno z tych æwiczeñ, które rozwijaj¹ zarówno masê miêœni dwug³owych, jak i charakterystyczny zaokr¹glony kszta³t. Trzeba je wykonywaæ z du¿¹ koncentracj¹. Siadamy na ³awce skoœnej, o nachyleniu ok.45 stopni. Przedramiona powinny byæ lekko odchylone od tu³owia, a ³okcie przylegaæ do niego. Wymodelowaniu kszta³tu miêœni s³u¿y „supinacja” nadgarstka','9');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('62','Uginanie ramion podchwytem stoj¹c-z r¹czk¹ wyci¹gu','Jak w æwiczeniu ze sztanga,(gdy wykonujemy æwiczenie obiema rêkami), tylko gryf sztangi zastêpujemy dr¹¿kiem wyci¹gu, b¹dŸ r¹czk¹ wyci¹gu,(gdy wykonujemy æwiczenie jednor¹cz).','9');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('63','Wyciskanie "francuskie" sztangi w siadzie','£okcie powinny trwaæ nieruchomo(jak najbli¿ej g³owy) podczas æwiczenia. Zakres ruchu:od pe³nego wyprostu ramion, do pe³nego zgiêcia w ³okciach. Przy pe³nym zgiêciu ramion, gdy sztanga znajduje siê za g³ow¹, nie powinno siê traciæ nad ni¹ kontroli(swobodne opuszczenie jej przeci¹¿a mocno stawy ³okciowe, co mo¿e prowadziæ do kontuzji).Æwiczenie mo¿na wykonywaæ równie¿ zastêpuj¹c sztangê dr¹¿kiem wyci¹gu dolnego','9');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('64','Prostowanie ramienia ze sztangielk¹ w opadzie tu³owia','Przy wyprostowanych plecach pochylamy siê do przodu i opieramy jedn¹ rêk¹ o ³awkê. W drugiej trzymamy sztangielkê i unosimy ramiê nieco ponad liniê pleców(nie ni¿ej)-przedramiê prostopadle do pod³ogi. Z tej pozycji pracuj¹c tylko tricepsem prostujemy ramiê w ³okciu unosz¹c ciê¿ar a¿ do pe³nego wyprostu. W pozycji koñcowej zatrzymujemy na moment ruch dla lepszego napiêcia miêœni. Musimy zwracaæ szczególn¹ uwagê na to, by w trakcie æwiczenia w ruchu by³o jedynie przedramiê(praca w stawie ³okciowym).Nie wolno dopuszczaæ do bujania ramieniem. Ruch opuszczania wolniejszy od unoszenia, z pe³n¹ kontrol¹ ciê¿aru.','9');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('1','Rozci¹ganie klatki piersiowej','Stajemy przy futrynie lub stabilnym sprzêcie domowym w lekkim rozkroku, jedna rêka luŸno opuszczona, druga wyprostowana i zaparta (pod k¹tem 90 stopni wzglêdem tu³owia)o nasze stabilne oparcie. W tej pozycji wykonujemy skrêty tu³owia w przeciwnym kierunku do rozci¹ganej strony klatki','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('2','Rozci¹ganie klatki piersiowej','Rozci¹ga obie czêœci klatki piersiowej jednoczeœnie-stajemy przy œcianie(ty³em do niej)-wyci¹gamy do ty³u wyprostowane ramiona i opieramy je wewnêtrznymi czêœciami d³oni o œcianê, na wysokoœci nieco powy¿ej pasa. Pozostaj¹ one przez ca³y czas æwiczenia w jednakowej pozycji. Z tej pozycji wykonujemy p³ytkie przysiady, rozci¹gaj¹c jednoczeœnie miêsnie klatki i obrêczy barkowej. Nale¿y wykonywaæ to æwiczenie z du¿ym wyczuciem, poniewa¿ zbyt g³êbokie(lub zbyt szybkie)opuszczanie tu³owia mo¿e spowodowaæ kontuzjê stawu barkowego.','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('3','Rozci¹ganie miêœni trójgowych ramion','Stoj¹c w lekkim rozkroku unosimy jedna rêkê, (której miêœnie bêdziemy rozci¹gaæ)pionowo w górê, zginaj¹c j¹ jednoczeœnie maksymalnie w ³okciu. Drug¹ rêk¹ chwytamy za ³okieæ i przyci¹gamy go za g³owê.','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('4','Rozci¹ganie miêœni dwugowych ramion','Klêkamy na pod³odze opieraj¹c ramiona o pod³ogê wewnêtrzn¹ stron¹ d³oni, palcami skierowanymi w naszym kierunku. W tej pozycji prostujemy ramiona w ³okciach, rozci¹gaj¹c jednoczeœnie miêœnie dwug³owe ramion(fot.3).Æwiczenie to rozci¹ga równie¿ miêœnie wewnêtrznej czêœci przedramion(zginacze nadgarstka).','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('5','Rozci¹ganie miêœni przedramion','Stoj¹c w lekkim rozkroku, d³oni¹ jednej rêki chwytamy za palce drugiej(wyprostowanej).W tej pozycji przyci¹gamy palce do siebie odginaj¹c jednoczeœnie d³oñ w nadgarstku do góry.(fot.4).Drugie æwiczenie jest podobne: stoj¹c w lekkim rozkroku ³¹czymy rêce ze sob¹ tak, by styka³y siê ca³ymi wewnêtrznymi stronami i palcami(palce skierowane w naszym kierunku).Z tej pozycji staramy siê prostowaæ ramiona w ³okciach, jednoczeœnie rozci¹gaj¹c miêœnie przedramion.','1');
