Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('8','Rozci¹ganie miêœni czwarogowych  ud','Stajemy na jednej nodze(najlepiej przy œcianie lub innym punkcie podparcia), drug¹ uginamy w kolanie i chwytamy rêk¹ za stopê w kostce(lewa noga-lewa rêka, prawa noga-prawa rêka). Z tej pozycji przyci¹gamy ugiêt¹ nogê maksymalnie do góry.','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('9','Rozci¹ganie miêœni wewnêtrznych ud','K³adziemy siê na plecach przy œcianie tak, by nogi opiera³y siê o ni¹ na ca³ej swojej d³ugoœci(poœladki dotykaj¹ œciany).W tej pozycji robimy pog³êbianie nogami do do³u(d¹¿¹c do szpagatu)pamiêtaj¹c, by przez ca³y czas nogi przylega³y do powierzchni œciany','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('10','Rozci¹ganie miêœni wewnêtrznych ud','wykonujemy w siadzie p³askim-nogi ugiête w kolanach, stopy z³¹czone podeszwami, chwytamy d³oñmi za stopy, ³okcie przyciœniête do ud od wewnêtrznej strony. Z tej pozycji napieramy przedramionami na uda, by pog³êbiæ ich rozchylenie','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('11','Rozci¹ganie miêœni ³ydek','Do æwiczenia jest potrzebna du¿a podk³adka, lub najlepiej schody. Trzymaj¹c siê dla zachowania równowagi porêczy(lub czegoœ stabilnego) wykonujemy na jednej nodze(na przemian)pog³êbianie piêt¹, rozci¹gaj¹c jednoczeœnie miêœnie ³ydek','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('12','Rozci¹ganie miêœni piszczelowych','Siadamy na pod³odze(materacu)w ten sposób, ¿e nogi mamy ugiête w kolanach, a do pod³ogi przylegaj¹ jedynie podudzia przedni¹ powierzchni¹(piszczelami).Piêty pod poœladkami, stopy wyprostowane - przylegaj¹ górnymi czêœciami do pod³ogi. Z tej pozycji podnosimy siê z poœladków i siadamy ponownie jednoczeœnie rozci¹gaj¹c miêœnie piszczelowe','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('13','Rozci¹ganie miêœni najszerszych grzbietu','Do tego æwiczenia jest potrzebny punkt oparcia-mo¿e byæ to krzes³o. Splatamy ramiona nad g³ow¹ ³¹cz¹c przedramiona ze sob¹, chwytaj¹c jednoczeœnie za ³okcie od zewn¹trz. Tak z³¹czone przedramiona k³adziemy na naszej podporze(krzeœle)jednoczeœnie klêcz¹c na kolanach przed krzes³em. Z tej pozycji wykonujemy pog³êbianie tu³owia, jednoczeœnie rozci¹gaj¹c miêsnie najszersze grzbietu','1');
