Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('15','Rozci¹ganie miêœni dolnego grzbietu','K³adziemy siê na plecach na pod³odze, ramiona rozk³adamy szeroko na pod³odze, z tej pozycji jedna nogê unosimy i dotykamy ni¹(wewnêtrzna stron¹) pod³ogi po stronie przeciwnej, na wysokoœci pasa. Jednoczeœnie obracamy biodra w tym samym kierunku. Druga noga pozostaje przez ca³y czas nieruchoma i przylega do pod³ogi. Takie ruchy wykonujemy na przemian lew¹ i praw¹ nog¹','1');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('16','Rozci¹ganie miêœni dolnego grzbietu','K³adziemy siê p³asko na pod³odze(lub materacu) na plecach. Z tej pozycji unosimy nogi i czêœæ tu³owia ku górze tak, by nogi by³y skierowane pionowo ku górze, ramiona ugiête w ³okciach, podpieraj¹ biodra-taka pozycja jest wyjœciow¹ -z niej opuszczamy nogi ku g³owie tak, by kolana dotknê³y pod³ogi obok g³owy. Przytrzymujemy w tej pozycji ruch przez chwilê i powracamy do pozycji wyjœciowej. Pamiêtajmy o kontrolowanym ruchu-gwa³townoœæ podczas wykonania tego æwiczenia grozi kontuzj¹','1');
