Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('24','Wyciskanie sztangi zza g³owy','W pozycji stoj¹cej: stajemy w rozkroku nieco szerszym, ni¿ barki (inna forma æwiczenia zak³ada wysuniêcie jednej nogi nieco w przód, dla lepszej równowagi) - klatka piersiowa wypchniêta ku przodowi, zachowana naturalna krzywizna krêgos³upa-pracuj¹ podczas æwiczenia tylko ramiona i barki (staramy siê unikaæ dodatkowych ruchów tu³owia i nóg), uchwyt nieco szerszy, ni¿ rozstaw barków.  W pozycji siedz¹cej: staramy siê zwracaæ du¿¹ uwagê na prawid³ow¹ pozycjê-przez ca³y czas nale¿y mieæ wypchniêt¹ ku przodowi klatkê piersiow¹ i zachowywaæ naturalna krzywiznê krêgos³upa. Taka pozycja zabezpiecza (oczywiœcie nie w pe³ni) przed urazami dolnego odcinka krêgos³upa. (mo¿na zastosowaæ oparcie o ³awkê-zmniejsza naciski na dyski miêdzykrêgowe).','3');
