Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('25','Arnoldki','æwiczenie mo¿na wykonywaæ zarówno w pozycji stoj¹cej, jak i siedz¹cej -z ³okciami przy tu³owiu chwytamy sztangielki i unosimy je na wysokoœæ barków tak, aby palce d³oni by³y skierowane do nas (podchwyt), równym tempem wypychamy sztangielki ponad g³owê do pozycji, w której jeszcze nie s¹ zablokowane ramiona-podczas wyciskania sztangielek obracamy dlonie tak,aby w koñcowej  fazie ruchu palce by³y skierowane do przodu (nachwyt) - w szczytowym punkcie powtórzenia wstrzymujemy ruch na moment, po czym opuszczamy sztangielki do pozycji wyjœciowej. Unikajmy blokowania ramion nad g³ow¹-dziêki temu utrzymamy sta³e napiêcie æwiczonych miêœni','3');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('26','Unoszenie sztangielek w opadzie tu³owia','æwiczenie wykonujemy w pozycji siedz¹cej lub stoj¹cej-W pozycji stoj¹cej: tu³ów ustawiamy w po³o¿eniu zbli¿onym do prostopad³ego do pod³o¿a i staramy siê w trakcie ruchu nie wykonywaæ nim tzw. bujania-utrzymujemy mo¿liwie sztywno. Z pozycji wyjœciowej ruchem kolistym unosimy sztangielki maksymalnie w górê, utrzymuj¹c przez ca³y czas æwiczone miêœnie w stanie napiêcia. Staramy siê, aby w ruchu powrotnym sztangielki porusza³y siê po tym samym torze. Jak w poprzednim æwiczeniu ,mo¿na w pozycji szczytowej przytrzymaæ przez chwilê sztangielki w celu dodatkowego napiêcia miêœni.','3');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('27','Unoszenie ramion w przód ze sztangielkami','to æwiczenie wykonujemy w pozycji stoj¹cej- mo¿na równie¿ wykonywaæ w pozycji siedz¹cej. Technika-jak wy¿ej, z ta ró¿nic¹, ¿e mo¿na wykonywaæ ruchy na  obiema rêkami jednoczeœnie, lub pojedynczo (jedna rêka w gorê, druga w spoczynku, lub jedna rêka w górê, a druga w tym czasie  porusza siê w dó³).','3');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('28','Wyciskanie sztangielek','D³onie ze sztangielkami przez ca³y czas trzymamy tak, aby ich wewnêtrzne czêœci skierowane by³y do przodu(inna wersja przewiduje uchwyt m³otkowy-d³onie zwrócone w czasie ca³ego ruchu palcami w kierunku g³owy).Ruch powinien odbywaæ siê  pod pe³n¹ kontrol¹ ciê¿aru-wa¿na jest równie¿ pozycja podczas æwiczenia-podobna do pozycji przy wyciskaniu sztangi. (wypchniêta klatka, naturalna krzywizna krêgos³upa)','3');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('29','Unoszenie sztangielek bokiem w górê',' æwiczenie mo¿na wykonywaæ w pozycji stoj¹cej  lub siedz¹cej, obur¹cz lub jednor¹cz. W pozycji wyjœciowej tu³ów lekko pochylony, rêce ze sztangielkami nieco ugiête w ³okciach, opuszczone w dó³, d³onie wewnêtrznymi stronami skierowane do œrodka. Ruch unoszenia rozpoczynamy przy ugiêtych rêkach, ³okcie w ka¿dej fazie ruchu wyprzedzaj¹ d³onie. Sztangielki unosimy powy¿ej linii barków i bez zatrzymania opuszczamy powoli w dó³ (lub przytrzymujemy w pozycji szczytowej przez chwilê w celu dodatkowego napiêcia miêœni). Æwiczenie to mo¿na równie¿ wykonywaæ jednor¹cz sztangielk¹ w odchyleniu-chwytamy siê porêczy, drabinek lub jakiegoœ innego przyrz¹du i odchylamy tu³ów w bok (jedna rêk¹ trzymamy siê porêczy, a w drugiej trzymamy sztangielkê) i unosimy sztangielkê bokiem w górê do poziomu (w tym punkcie mo¿na zatrzymaæ ruch na chwilê) nastêpnie opuszczamy j¹ do pozycji wyjœciowej.','3');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('30','Podci¹ganie sztangi wzd³u¿ tu³owia','Rozkrok nieco szerszy od rozstawu barków, uchwyt na szerokoœæ ramion (inna wersja przewiduje szerszy rozstaw d³oni, nawet szerszy ni¿ rozstaw barków-zaanga¿owane s¹ wtedy bardziej boczne aktony miêsni naramiennych, a ruch koñczymy na wysokoœci klatki piersiowej). Ruchem wolnym i kontrolowanym unosimy sztangê w kierunku brody, staraj¹c siê aby przemieszcza³a siê mo¿liwie najbli¿ej tu³owia. £okcie przez ca³y czas trzymamy powy¿ej gryfu sztangi. Ruch unoszenia koñczymy, gdy sztanga znajdzie siê na wysokoœci klatki piersiowej (lub staramy siê podci¹gn¹æ sztangê a¿ do brody), opuszczamy równie¿ powoli, unikamy odchylania i bujania tu³owia. Koncentrujemy siê na unoszeniu ³okci, a sztanga pod¹¿y za nimi.','3');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('31','Wyciskanie sztangi w le¿eniu na ³awce poziomej','K³adziemy siê na ³awce tak, by nogi ugiête by³y pod k¹tem prostym i przylega³y do pod³o¿a. Uchwyt œredni(taki, by po opuszczeniu sztangi na klatkê ramiona tworzy³y z przedramionami k¹t prosty-kciuk dla bezpieczeñstwa powinien obejmowaæ sztangê-choæ wielu bardziej doœwiadczonych kulturystów preferuje raczej tzw. ”ma³pi chwyt” (kciuk ponad gryfem).Opuszczamy sztangê na klatkê na wysokoœæ ok.1 cm powy¿ej brodawek. Przy opuszczaniu sztangi wykonujemy g³êboki wdech-wydychamy powietrze w trakcie wyciskania. Mo¿na okresowo praktykowaæ przytrzymywanie sztangi przez chwilê na klatce przed wyciœniêciem.(szczególnie przydatne, je¿eli mamy w planach ewentualne starty w zawodach w wyciskaniu)-dodatkowo rozbudowuje si³ê-pobudza do dodatkowego wysi³ku. £okcie prowadzimy w trakcie ca³ego ruchu po bokach-tak by nie „ucieka³y”do œrodka. Ruch wyciskania koñczymy(dla lepszego napiêcia miêœni)zanim ³okcie zostan¹ zblokowane. ','4');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('32','Podci¹ganie na dr¹¿ku szerokim uchwytem (nachwyt)','Nie ma drugiego takiego æwiczenia pod wzglêdem wszechstronnoœci rozwoju miêsni grzbietu. Æwiczenie to mo¿na wykonywaæ do karku i do brody, lecz wersja do karku jest mniej naturalna dla stawów. Chwytamy dr¹¿ek nachwytem na szerokoœæ tak¹, by po podci¹gniêciu ramiona z przedramionami tworzy³y k¹t prosty(w przybli¿eniu).Nogi ugiête w kolanach(dla lepszej stabilnoœci mo¿na je spleœæ).£okcie pracuj¹ w p³aszczyŸnie pleców-w jednej linii. Wdech robimy przed rozpoczêciem ruchu podci¹gania-wydech dopiero, gdy jesteœmy ju¿ u góry. Ruch podci¹gania koñczymy w momencie, gdy nasza broda(lub kark) jest na wysokoœci dr¹¿ka lub nieco ponad nim. Opuszczamy siê wolno i pod pe³n¹ kontrol¹. Jeœli jesteœmy bardziej zaawansowani i mo¿emy wykonaæ wiele powtórzeñ w tym æwiczeniu, to mo¿na zastosowaæ dodatkowe obci¹¿enie','5');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('33','Przysiady ze sztang¹ na barkach','Wchodzimy pod sztangê stoj¹c¹ na stojakach, barki opuszczone i odwiedzione w ty³, gryf sztangi dotyka naszego karku na miêœniach czworobocznych grzbietu(ich górnej czêœci), d³onie rozstawione w wygodnej i stabilnej pozycji na gryfie, klatka wypchniêta ku przodowi, naturalna krzywizna krêgos³upa-dolny odcinek grzbietu wypchniêty do przodu, rozstaw stóp w zale¿noœci od naszego poczucia stabilnoœci(zmiana rozstawu stóp powodowaæ bêdzie atak na miêœnie pod innym k¹tem), najlepiej nieco szerzej, ni¿ barki, ca³e stopy przylegaj¹ do pod³ogi, ciê¿ar ma opieraæ siê na piêtach, g³owa zadarta nieco do ty³u. Z tej pozycji nabieramy g³êboko powietrza i œci¹gamy sztangê ze stojaków i rozpoczynamy ruch w dó³(najlepiej przed tym wypuszczaj¹c powietrze po œci¹ganiu sztangi ze stojaków i nabieraj¹c go ponownie). Przez ca³y czas plecy wygiête w jednakowy sposób, pracuj¹ tylko nogi.','6');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('34','Wspiêcia na palce w staniu',' Istotnym elementem w tym æwiczeniu jest u¿ycie grubej podk³adki pod palce stóp, która pozwala zwiêkszyæ znacznie zakres ruchu, a co za tym idzie-poprawiæ efektywnoœæ æwiczenia. Pozycja wyjœciowa, to wyprostowany tu³ów i plecy, nogi wyprostowane w kolanach, rozkrok 25-30 cm, palce stóp(wraz ze stawami ³¹cz¹cymi je ze œródstopiem) na podk³adce-miêsnie ³ydek rozci¹gniête maksymalnie. Z takiej pozycji rozpoczynamy wspiêcia. Ruch powinien byæ wolny i dok³adny, ze sta³ym „czuciem” pracy miêœni. Nale¿y unikaæ odbijania siê piêt od pod³ogi.','7');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('35','Sk³ony w le¿eniu p³asko','K³adziemy siê na materacu lub ³awce. Nogi ugiête, rêce nad g³ow¹ i unosimy tu³ów w górê. Pierwsza do góry unosi siê g³owa, potem barki, a na koñcu reszta tu³owia','8');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('36','Uginanie ramion ze sztang¹ stoj¹c podchwytem','Tu³ów podczas æwiczenia utrzymujemy w pozycji wyprostowanej(bez bujania nim). Zakres ruchu: od pe³nego rozgiêcia bicepsów(nie ramion)do pe³nego ich skurczu. Pe³ne rozci¹gniêcie bicepsów, to nie to samo, co pe³ny wyprost ramion. Nale¿y unikaæ(nie tylko w tym æwiczeniu) tzw. ”przeprostów” ramion, czyli nadmiernego ich wyprostowywania(do pe³nego zakresu ruchu w stawie ³okciowym).£okcie przez ca³y czas przylegaj¹ do tu³owia-nie powinny uciekaæ na boki, ani w przód, gdy¿ powoduje to zaanga¿owanie innych miêœni do pracy. Powietrza nabieramy w pozycji wyjœciowej, wypuszczamy je dopiero po przejœciu ciê¿aru przez najtrudniejszy punkt ruchu. ','9');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('37','Wyciskanie sztangielek w le¿eniu na ³awce poziomej','7','4');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('38','Wyciskanie sztangi w le¿eniu na ³awce skoœnej-g³ow¹ w górê',')£awkê ustawiamy pod k¹tem 30-45 stopni(wiêkszy k¹t bardziej anga¿uje w æwiczeniu miêœnie naramienne), k³adziemy siê g³ow¹ do góry. Uchwyt sztangi, oddychanie, prowadzenie ³okci, jak w æwiczeniu na ³awce p³askiej. Chwytamy sztangê i opuszczamy j¹ na klatkê-ok.10 cm. poni¿ej szyi. Staramy siê skupiaæ uwagê na anga¿owaniu w pracê tylko miêsni piersiowych i maksymalnym wy³¹czeniu z niej miêsni naramiennych. W tym celu mo¿na lekko wygi¹æ grzbiet, jednoczeœnie wypychaj¹c klatkê do przodu. Nie wolno jednak odrywaæ zbytnio pleców od ³awki, a biodra musz¹ bezwzglêdnie przylegaæ do ³awki. ','4');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('39','Wyciskanie sztangielek w le¿eniu na ³awce skoœnej-g³ow¹ w górê','Pozycja jak w æwiczeniu ze sztang¹-dodatkowe mo¿liwoœci jak w æwiczeniu ze sztangielkami na ³awce p³askiej.','4');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('40','Rozpiêtki ze sztangielkami w le¿eniu na ³awce poziomej','Æwiczenie rozpoczynamy z ramionami wyprostowanymi-prostopad³ymi do pod³o¿a( palce d³oni skierowane s¹ do siebie), a w trakcie ruchu lekko uginamy je w ³okciach. Nabieramy powietrza, gdy sztangielki s¹ u góry(na pocz¹tku ruchu) wydychamy je, gdy sztangielki wêdruj¹ do góry. W koñcowej fazie ruch mo¿na zatrzymaæ na chwilê w celu lepszego napiêcia miêœni. Staramy siê nie uderzaæ sztangielkami o siebie, ale zatrzymywaæ ruch zanim siê zetkn¹. Wa¿ne jest wykonywanie pe³nego zakresu ruchu(by dostatecznie rozci¹gn¹æ miêœnie)-im wiêkszy zakres wykonanego ruchu, tym pe³niejszy ogólny rozwój miêœnia.','4');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('41','Pompki na porêczach','W tym æwiczeniu, podobnie jak przy wyciskaniu w¹sko równie¿ wa¿ne jest by pracê wykonywa³y w g³ównym stopniu miêœnie piersiowe, w mniejszym stopniu chodzi nam o pracê miêœni trójg³owych ramion. Elementem decyduj¹cym o wiêkszym zaanga¿owaniu jednych, b¹dŸ drugich miêœni jest pozycja tu³owia i u³o¿enie ³okci. Nale¿y wypracowaæ takie u³o¿enie tu³owia, przy którym g³ówn¹ pracê bêd¹ wykonywa³y miêœnie piersiowe, a ³okcie pracowaæ powinny w pewnym oddaleniu od tu³owia. Dla lepszego wyeliminowania pracy tricepsów i lepszego napiêcia miêsni piersiowych mo¿na równie¿ nie prostowaæ ramion do koñca.','4');
Insert into MUSCLESMAN.EXCERCISES (EXCERCISE_ID,EXCERCISE_NAME,EXCERCISE_DESCR,TYPE) values ('42','Podci¹ganie sztangi w opadzie (wios³owanie)','Stajemy nad sztang¹ w rozkroku na szerokoœæ barków, pochylamy tu³ów do pozycji prawie równoleg³ej do pod³o¿a, plecy w dolnym odcinku mocno ugiête do œrodka, nogi lekko ugiête w kolanach przez ca³y czas trwania æwiczenia. Wdech bierzemy w momencie rozpoczêcia podci¹gania-wydech dopiero, gdy sztanga dochodzi do brzucha(lub do klatki). Sztangê chwytamy na szerokoœæ nieco wiêksz¹ od barków i podci¹gamy j¹ do brzucha','5');
