--  DDL for Function F_ADDAPPUSER
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_ADDAPPUSER" (U_NAME IN VARCHAR2, U_PASS in varchar2) RETURN NUMBER IS

CURSOR searchForUser IS SELECT USER_ID FROM APPUSER WHERE upper(user_name) in (upper(U_NAME));
foundUser APPUSER.USER_ID%TYPE;
RET NUMBER ;
userExists EXCEPTION;
BEGIN

OPEN searchForUser;

    FETCH searchForUser into foundUser;
    
    IF searchForUser%NOTFOUND then 
      P_ADDAPPUSER(U_NAME,U_PASS);
      RETURN 0;
    ELSE
      RAISE userExists;
    END IF;   
  CLOSE searchForUser;

EXCEPTION
WHEN userExists THEN
   P_ERROR(SQLERRM, 'USER_NAME ' || U_NAME || ' already exists!!',  $$PLSQL_UNIT );
   return -1;
WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
END;

/
--------------------------------------------------------
--  DDL for Function F_AUTOLOGIN
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_AUTOLOGIN" (U_ID IN NUMBER, SESSIONID in number) RETURN APPUSER.USER_NAME%type IS

CURSOR searchForUser IS SELECT USER_ID FROM APPUSERREMEMBERLOGIN WHERE REMEMBER_LOGIN = 'true' and USER_ID = U_ID;
CURSOR searchForUser2 IS SELECT USERID FROM APPSESSION WHERE VALIDTO > sysdate and USERID = U_ID;
foundUser APPUSER.USER_ID%TYPE;
RET NUMBER ;
userNotExists EXCEPTION;
BEGIN


OPEN searchForUser;

    FETCH searchForUser into foundUser;
    IF searchForUser%NOTFOUND then 
      open searchForUser2;
         FETCH searchForUser2 into foundUser;
          IF searchForUser2%NOTFOUND then 
              RAISE userNotExists;
          ELSE
            P_ADDLOGININFO(foundUser, 'true', SESSIONID);
             RETURN foundUser;
          END IF;
      CLOSE searchForUser2;
    ELSE
      P_ADDLOGININFO(foundUser, 'true', SESSIONID);
      RETURN foundUser;
    END IF;   
  CLOSE searchForUser;

EXCEPTION
WHEN userNotExists THEN
   P_ERROR(SQLERRM, 'User with id ' || U_ID || ' not found!',  $$PLSQL_UNIT );
   return -1;
WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
END;

/
--------------------------------------------------------
--  DDL for Function F_FINDUSER
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_FINDUSER" (U_NAME IN VARCHAR2, U_PASS in varchar2) RETURN NUMBER IS

CURSOR searchForUser IS SELECT USER_ID, USER_PASSWORD FROM AppUser WHERE upper(user_name) in (upper(U_NAME));
foundUser APPUSER.USER_ID%TYPE;
foundUserPass APPUSER.USER_PASSWORD%TYPE;
RET NUMBER ;
hashPass APPUSER.USER_PASSWORD%TYPE;
userNotExists EXCEPTION;
passwordIncorect EXCEPTION;
BEGIN

SELECT ORA_HASH(U_PASS) INTO hashPass FROM DUAL;

OPEN searchForUser;

    FETCH searchForUser into foundUser, foundUserPass;
    IF searchForUser%NOTFOUND then 
      RAISE userNotExists;
    ELSIF hashPass != foundUserPass then
      RAISE passwordIncorect;
    ELSE
      RETURN foundUser;
    END IF;   
  CLOSE searchForUser;

EXCEPTION
WHEN userNotExists THEN
   P_ERROR(SQLERRM, 'User ' || U_NAME || ' does not exists!!',  $$PLSQL_UNIT );
   return -1;
WHEN passwordIncorect THEN
   P_ERROR(SQLERRM, 'Password for ' || U_NAME || ' is incorrect!!',  $$PLSQL_UNIT );
   return -1;
WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
END;

