--  DDL for Function F_GETACHIEW
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_GETACHIEW" (u_id in number) return USERACHIEWT is
cursor ach is select * from USER_ACHIEVEMENTS where USERID = u_id;

RETURN_VALUES USERACHIEWT;

rowtyp USER_ACHIEVEMENTS%rowtype;

nam EXCERCISES.EXCERCISE_NAME%type;
dat USER_ACHIEVEMENTS.ACHIEW_DATE%type;
achi USER_ACHIEVEMENTS.ACHIEVEMENT%type;

begin

  IF NOT ach%ISOPEN THEN
      OPEN ach;
   END IF;
  RETURN_VALUES := USERACHIEWT();
     loop
      EXIT WHEN ach%NOTFOUND;
      
      fetch ach into rowtyp;
      
      select EXCERCISE_NAME into nam from EXCERCISES where EXCERCISE_ID = rowtyp.EXCERCISE;

      RETURN_VALUES.extend;
      RETURN_VALUES(RETURN_VALUES.last)  := USERACHIEW(nam, rowtyp.ACHIEW_DATE, rowtyp.ACHIEVEMENT);

    end loop;

close ach;

RETURN RETURN_VALUES;
exception
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 
END;

