--------------------------------------------------------
--  DDL for Function F_GETTRAINING
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_GETTRAINING" (u_id in number) return USERTRENINGT 
IS 
cursor allexcercises is select excercise_id from excercises;
returnval USERTRENINGT;

id excercises.excercise_id%type;
usr_excr APPUSER_EXCERCISE.EXCERCISEID%type;
usr_exp APPUSERDATA.EXPERIENCE%type;
usr_trtype APPUSERDATA.TYPEOFTRENING%type;
typeid INTENSITY.TYPE_OF_EXCERCISE%type;

typeofexcr TYPE_OF_EXCERCISE.TYPE_NAME%type;
dayweek DAYOFWEEK.DAYOFWEEK_ID%type;
excr EXCERCISES.EXCERCISE_NAME%type;
repe INTENSITY.REPEAT%type;
serie INTENSITY.SERIES%type;

 NO_TRENING exception ;

begin

  select EXPERIENCE into usr_exp from APPUSERDATA where USER_ID = u_id;
  select TYPEOFTRENING into usr_trtype from APPUSERDATA where USER_ID = u_id;
  
  open allexcercises;
  returnval := USERTRENINGT();
    loop
     EXIT WHEN allexcercises%NOTFOUND;
     fetch allexcercises into id;
     begin
            select distinct EXCERCISEID into usr_excr from APPUSER_EXCERCISE where EXCERCISEID = id and userid = u_id;
     
     IF usr_excr IS NOT NULL THEN
        dbms_output.put_line ('usr_excr ' || usr_excr);
       select distinct EXCERCISE_NAME into excr from EXCERCISES where EXCERCISE_ID = usr_excr;
       select distinct TYPE into typeid from EXCERCISES where EXCERCISE_ID = usr_excr;
--       
       SELECT distinct REPEAT INTO repe FROM INTENSITY where EXPERIENCE = usr_exp AND TRENING_TYPE = usr_trtype AND TYPE_OF_EXCERCISE=typeid;
       SELECT distinct SERIES INTO serie FROM INTENSITY where EXPERIENCE = usr_exp AND TRENING_TYPE = usr_trtype AND TYPE_OF_EXCERCISE=typeid;
--       
      SELECT distinct DAYOFWEEK INTO dayweek FROM DAYOFWEEK_TRENINGTYPE WHERE USERID = u_id and TRENINGTYPE = typeid;
--      
       SELECT distinct TYPE_NAME INTO typeofexcr FROM TYPE_OF_EXCERCISE WHERE TYPE_OF_EXCERCISE_ID = typeid;
--       
--       
        returnval.extend;
        returnval(returnval.last)  := USERTRENING(dayweek, typeofexcr, excr, repe, serie);
        
       dbms_output.put_line (dayweek || ' ' || typeofexcr || ' ');
         
     END IF;
    exception
     when no_data_found
then
dbms_output.put_line ('No data found '||id);
     end;
     
    end loop;
  
  
  close allexcercises;
  
  IF returnval IS NULL THEN
  
        returnval.extend;
        returnval(returnval.last)  := USERTRENING('no trening found', '', '', 0, 0);
        
        RAISE NO_TRENING;
  END IF ;
  
RETURN returnval;
exception
  WHEN NO_TRENING THEN
    P_ERROR(SQLERRM, 'NO TRENING FOUND FOR USER '||u_id ,  $$PLSQL_UNIT );
    RAISE_APPLICATION_ERROR (-20001,'An error was encountered -  NO TRENING'||SQLCODE||' -ERROR- '||SQLERRM);
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 
END;

