--------------------------------------------------------
--  DDL for Function F_LASTNEGLOGIN
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_LASTNEGLOGIN" (U_ID in NUMBER) RETURN VARCHAR2 IS

CURSOR searchForLastNegNotSeenLogin IS SELECT USER_ID, LOGIN_DATE FROM APPUSERLOGININFO WHERE USER_ID = U_ID AND SUCCESS = 'false' AND SEEN = 'false' ORDER BY LOGIN_DATE ASC;
foundUser APPUSERLOGININFO.USER_ID%TYPE;
foundUserLoginDate APPUSERLOGININFO.LOGIN_DATE%TYPE;
COUNTER VARCHAR2(1000);
DATEU VARCHAR2(1000);
DATEU2 VARCHAR2(1000);
RET VARCHAR2(1000);
n number :=0;
BEGIN

OPEN searchForLastNegNotSeenLogin;


    FOR i IN (SELECT * FROM APPUSERLOGININFO) LOOP
      FETCH searchForLastNegNotSeenLogin into foundUser, foundUserLoginDate;
      
      IF searchForLastNegNotSeenLogin%FOUND then 
        n:=n+1;
      END IF;
    
    END LOOP;
    
    P_ADDSEENDATE(foundUser);
    
    SELECT to_CHAR(n) into COUNTER FROM DUAL;
    SELECT to_CHAR(SUBSTR(foundUserLoginDate, 1,17)) into DATEU FROM DUAL;
    
        
    IF n < 1 THEN
      RET:= COUNTER;
    ELSE
      RET:=CONCAT(CONCAT(COUNTER, ' '), DATEU);
    END IF;

CLOSE searchForLastNegNotSeenLogin;

RETURN RET;

EXCEPTION
WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
END;

/
--------------------------------------------------------
--  DDL for Function F_LOGIN
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_LOGIN" (U_NAME IN VARCHAR2, U_PASS in varchar2, SESSIONID in number) RETURN NUMBER IS

CURSOR searchForUser IS SELECT USER_ID, USER_PASSWORD FROM AppUser WHERE upper(user_name) in (upper(U_NAME));
foundUser APPUSER.USER_ID%TYPE;
foundUserPass APPUSER.USER_PASSWORD%TYPE;
RET NUMBER ;
hashPass APPUSER.USER_PASSWORD%TYPE;
userNotExists EXCEPTION;
passwordIncorect EXCEPTION;
BEGIN

SELECT ORA_HASH(U_PASS) INTO hashPass FROM DUAL;
--SELECT U_PASS INTO hashPass FROM DUAL;

OPEN searchForUser;

    FETCH searchForUser into foundUser, foundUserPass;
    IF searchForUser%NOTFOUND then 
      RAISE userNotExists;
    ELSIF hashPass != foundUserPass then
      P_ADDLOGININFO(foundUser, 'false', 0);
      RAISE passwordIncorect;
    ELSE
      P_ADDLOGININFO(foundUser, 'true', SESSIONID);
      RETURN foundUser;
    END IF;   
  CLOSE searchForUser;

EXCEPTION
WHEN userNotExists THEN
   P_ERROR(SQLERRM, 'User ' || U_NAME || ' does not exists!!',  $$PLSQL_UNIT );
   return -1;
WHEN passwordIncorect THEN
   P_ERROR(SQLERRM, 'Password for ' || U_NAME || ' is incorrect!!',  $$PLSQL_UNIT );
   return -1;
WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   return -1;
END;

/
--------------------------------------------------------
--  DDL for Function F_NEARESTTRAINING
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_NEARESTTRAINING" (u_id in number, day_Of_week in number) return  SHOWNEARESTTRAINING 
IS
CURSOR excer_ids IS
select EXCERCISES.EXCERCISE_ID, APPUSERDATA.EXPERIENCE, DAYOFWEEK_TRENINGTYPE.TRENINGTYPE,  APPUSERDATA.TYPEOFTRENING
from EXCERCISES
join APPUSER_EXCERCISE 
on EXCERCISES.EXCERCISE_ID = APPUSER_EXCERCISE.EXCERCISEID
join APPUSERDATA
on APPUSERDATA.USER_ID = APPUSER_EXCERCISE.USERID
join DAYOFWEEK_TRENINGTYPE
on DAYOFWEEK_TRENINGTYPE.TRENINGTYPE = EXCERCISES.TYPE
WHERE APPUSER_EXCERCISE.USERID  = u_id and DAYOFWEEK = day_Of_week
ORDER BY EXCERCISES.EXCERCISE_ID;
RETURN_VALUES SHOWNEARESTTRAINING;
excer_name EXCERCISES.EXCERCISE_NAME%TYPE;
excer_desc EXCERCISES.EXCERCISE_DESCR%TYPE;
REP INTENSITY.REPEAT%TYPE;
SER INTENSITY.SERIES%TYPE;
ID EXCERCISES.EXCERCISE_ID%TYPE;
exp  APPUSERDATA.EXPERIENCE%type;
tr_type  APPUSERDATA.TYPEOFTRENING%TYPE;
ex_type  EXCERCISES.TYPE%TYPE;
i number:=0;
TYPE nextField IS RECORD(
              n EXCERCISES.EXCERCISE_NAME%TYPE, 
              d EXCERCISES.EXCERCISE_DESCR%TYPE, 
              R INTENSITY.REPEAT%TYPE
              , S INTENSITY.SERIES%TYPE);
BEGIN


  IF NOT excer_ids%ISOPEN THEN
      OPEN excer_ids;
   END IF;
  RETURN_VALUES := SHOWNEARESTTRAINING();
     loop
     EXIT WHEN excer_ids%NOTFOUND;
     
     FETCH excer_ids INTO ID, exp, ex_type, tr_type;
     
        SELECT EXCERCISE_NAME into excer_name FROM EXCERCISES WHERE EXCERCISE_ID = ID;
        SELECT EXCERCISE_DESCR into excer_desc FROM EXCERCISES WHERE EXCERCISE_ID = ID;
        
        SELECT REPEAT INTO REP FROM INTENSITY where EXPERIENCE = exp AND TRENING_TYPE = tr_type AND TYPE_OF_EXCERCISE=ex_type;
        SELECT SERIES INTO SER FROM INTENSITY where EXPERIENCE = exp AND TRENING_TYPE = tr_type AND TYPE_OF_EXCERCISE=ex_type;
        
        RETURN_VALUES.extend;
        RETURN_VALUES(RETURN_VALUES.last)  := NEARESTTRAINING(excer_name, excer_desc, REP, SER);
      

     END LOOP;
   
  CLOSE excer_ids;

RETURN RETURN_VALUES;
exception
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 
END;

/
--------------------------------------------------------
--  DDL for Function F_SHOWTRAINING
--------------------------------------------------------

  CREATE OR REPLACE FUNCTION "MUSCLESMAN"."F_SHOWTRAINING" (u_exp in number, u_trType in number) return userDefinedTreningTable IS
RETURN_VALUES userDefinedTreningTable;

BEGIN

select userDefinedTrening(TYPE, EXCERCISE_ID, EXCERCISE_NAME, REPEAT, SERIES)
BULK COLLECT INTO RETURN_VALUES
FROM intensity join EXCERCISES on intensity.TYPE_OF_EXCERCISE =EXCERCISES.TYPE
WHERE TRENING_TYPE =u_trType
AND EXPERIENCE = u_exp
ORDER BY TYPE;

RETURN RETURN_VALUES;

exception
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 
END;

