/
--------------------------------------------------------
--  DDL for Procedure P_ADDLOGININFO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE PROCEDURE "MUSCLESMAN"."P_ADDLOGININFO" 
(u_id in number, success in varchar2, session_id in number) is

user APPSESSION.USERID%type;

cursor finduser is SELECT userid from APPSESSION where userid = u_id;

 begin
   
  INSERT INTO APPUSERLOGININFO (USER_ID, LOGIN_DATE, SUCCESS) VALUES (u_id, sysdate, success);
  
  IF success = 'true' then
  
        IF NOT finduser%ISOPEN THEN
           OPEN finduser;
         END IF;
         
         fetch finduser into user;
         
         IF finduser%NOTFOUND THEN
         
            INSERT INTO APPSESSION VALUES (u_id, session_id, sysdate+(2/24));
            
          ELSE
            
            UPDATE APPSESSION SET sessionid = session_id, validto = sysdate+(2/24) WHERE userid = u_id;
            
          END IF;
            
  
  end if;
  
  commit;
  
  p_success('succesfully logged in: '||u_id , $$PLSQL_UNIT);
 
exception
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 end;

/
--------------------------------------------------------
--  DDL for Procedure P_ADDREMEMBERLOGIN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE PROCEDURE "MUSCLESMAN"."P_ADDREMEMBERLOGIN" 
(u_id in number, remember IN NUMBER) is

CURSOR isUserInTable IS select USER_ID from APPUSERREMEMBERLOGIN WHERE USER_ID = u_id;
userID APPUSERREMEMBERLOGIN.USER_ID%TYPE;
rem APPUSERREMEMBERLOGIN.REMEMBER_LOGIN%TYPE;
 begin
 
  IF remember = 0 THEN
    rem:='false';
  ELSE
    rem:='true';
  END IF;
 
  OPEN isUserInTable;
  
    FETCH isUserInTable INTO userID;
    
    IF isUserInTable%FOUND then 
      UPDATE APPUSERREMEMBERLOGIN 
      SET REMEMBER_LOGIN = rem
      where USER_ID = userID;
    ELSE 
      INSERT INTO APPUSERREMEMBERLOGIN (USER_ID, REMEMBER_LOGIN)
      VALUES (u_id, rem);
    END IF;   
    commit;
  
 
exception
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 end;

/
--------------------------------------------------------
--  DDL for Procedure P_ADDSEENDATE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE PROCEDURE "MUSCLESMAN"."P_ADDSEENDATE" 
(u_id in number) is

 begin
   
  UPDATE APPUSERLOGININFO 
  SET SEEN = 'true'
  where USER_ID = u_id
  AND seen = 'false'
  And SUCCESS = 'false';
  commit;
 
exception
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 end;

/
--------------------------------------------------------
--  DDL for Procedure P_ERROR
--------------------------------------------------------
set define off;

  CREATE OR REPLACE PROCEDURE "MUSCLESMAN"."P_ERROR" (errm in varchar2, errorTxt in varchar2, sqlUnit in varchar2) is
outFile  UTL_FILE.FILE_TYPE;
BEGIN
  outFile := UTL_FILE.FOPEN('ERRORLOG', 'error.log' , 'A');

  UTL_FILE.PUT_LINE(outFile , SYSDATE || ' -ERROR- ' || errm || ' ::: ' || errorTxt || ' ::: IN: ' || sqlUnit);
  UTL_FILE.FCLOSE(outFile);
  
END;

/
--------------------------------------------------------
--  DDL for Procedure P_LOGOUT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE PROCEDURE "MUSCLESMAN"."P_LOGOUT" 
(u_id in number) is

 begin
   
  UPDATE APPUSERREMEMBERLOGIN SET REMEMBER_LOGIN = 'false' where USER_ID = u_id;
  UPDATE APPSESSION SET VALIDTO = sysdate where USERID = u_id;
  
  
  
  commit;
  
  p_success('succesfully logged out: '||u_id , $$PLSQL_UNIT);
 
exception
 WHEN OTHERS THEN
   P_ERROR(SQLERRM, SQLCODE,  $$PLSQL_UNIT );
   RAISE_APPLICATION_ERROR (-20001,'An error was encountered - '||SQLCODE||' -ERROR- '||SQLERRM);
 end;

/
--------------------------------------------------------
--  DDL for Procedure P_SUCCESS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE PROCEDURE "MUSCLESMAN"."P_SUCCESS" (successTxt in varchar2, sqlUnit in varchar2) is
outFile  UTL_FILE.FILE_TYPE;
BEGIN
  outFile := UTL_FILE.FOPEN('ERRORLOG', 'error.log' , 'A');

  UTL_FILE.PUT_LINE(outFile , SYSDATE || ' -SUCCESS- ' || ' ::: ' || successTxt || ' ::: IN: ' || sqlUnit);
  UTL_FILE.FCLOSE(outFile);
  
END;

/
